<?php require __DIR__.'/../../layouts/header.php'; ?><div class="toolbar"><div><h1 class="page-title">Calendario de hitos MG</h1><p class="subtitle">Vista de seguimiento por cohorte: próximo, vencido o cumplido.</p></div><form method="get"><select name="id_cohorte" onchange="this.form.submit()"><option value="0">Todas las cohortes</option><?php foreach($cohortes as $c): ?><option value="<?=$c['id_cohorte']?>" <?=$coh==(int)$c['id_cohorte']?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach;?></select></form></div><div class="card"><div class="card-body"><div class="timeline"><?php foreach($hitos as $h): $cumplido=false;if($h['tipo']==='informe'){$s=$pdo->prepare('SELECT COUNT(*) FROM informes_avance i JOIN expedientes_mg x ON x.id_expediente=i.id_expediente WHERE i.id_hito=?');$s->execute([$h['id_hito']]);$cumplido=(int)$s->fetchColumn()>0;}elseif($h['tipo']==='defensa'){$s=$pdo->prepare('SELECT COUNT(*) FROM defensas_mg d JOIN expedientes_mg x ON x.id_expediente=d.id_expediente WHERE x.id_cohorte=? AND d.fecha<=CURDATE() AND d.estado="realizada"');$s->execute([$h['id_cohorte']]);$cumplido=(int)$s->fetchColumn()>0;} $estado=$cumplido?'cumplido':((!empty($h['fecha_limite'])&&$h['fecha_limite']<date('Y-m-d'))?'vencido':'proximo');?><div class="card" style="margin-bottom:12px"><div class="card-body"><strong><?=e($h['nombre'])?></strong><span class="badge badge-<?= $estado==='cumplido'?'success':($estado==='vencido'?'danger':'warning') ?>"><?=e($estado)?></span><div><?=e($h['cohorte_nombre'])?> · <?=e($h['etapa'])?> · <?=e($h['tipo'])?> · límite <?=e($h['fecha_limite']??'sin fecha')?></div><?php if($h['avance_esperado_pct']!==null): ?><small>Avance esperado: <?=e($h['avance_esperado_pct'])?>%</small><?php endif;?></div></div><?php endforeach;if(!$hitos): ?><p>No hay hitos cargados.</p><?php endif;?></div></div></div><?php require __DIR__.'/../../layouts/footer.php'; ?>
